visualizations.logic:
var tesseract = variables.tesseract;
var id = variables.id;
var billionsOfSar = variables.billionsOfSar;
var millionsOfSar = variables.millionsOfSar;
var months = variables.months;
var years = variables.years;
var lastYearAvailableExports = variables.lastYearAvailableExports;
var sar = formatters.sar;
var commas = formatters.commas;
var abbreviate = formatters.abbreviate;
var decimal = formatters.decimal;
var ref = libs.d3;
var nest = ref.nest;
var sum = ref.sum;
var max = ref.max;

var selector = "value"
var selectorName = "القيمة"
var measure = selector === "value" ? "Million SAR" : "Weight TONS"

var time = "monthly"// annual, monthly
var timeSelected = time === "annual" ? "Year" : "Month"
var timeID = time === "annual" ? "Year" : "Month ID"
var timeSelected_ = time === "annual" ? "Year" : "Month New"

var dataMonth = tesseract + "/data.jsonrecords?Country=" + id + "&cube=foreign_trade&drilldowns=Month,Trade+Flow&measures=" + measure + "&locale=" + locale
var dataYear = tesseract + "/data.jsonrecords?Country=" + id + "&cube=foreign_trade&drilldowns=Year,Trade+Flow&measures=" + measure + "&locale=" + locale;

var translations = {
  value: {en: "Value", ar: "القيمة"},
  title: {en: "Trade Balance", ar: "الميزان التجاري"},
  yAxisBillion: {en: "SAR Billions", ar: "مليار ريال سعودي" },
  yAxisMillion: {en: "SAR Millions", ar: "مليون ريال سعودي" },
  month: {en: "Month", ar: "الشهر"},
  year: {en: "Year", ar: "السنة"},
  flow: {en: "Flow", ar: "تدفق التجارة"},
  value_: {en: ("Value (" + billionsOfSar + ")"), ar: ("القيمة (" + billionsOfSar + ")")},
  tradeBalance: {en: "Trade Balance", ar: "الميزان التجاري"},
  exports: {en: "Exports", ar: "الصادرات"},
  imports: {en: "Imports", ar: "الواردات"},
  exports_value: {en: "Exports Value", ar: "قيمة الصادرات"},
  imports_value: {en: "Imports Value", ar: "قيمة الواردات"},
  exports_weight: {en: "Exports Weight", ar: "وزن الصادرات"},
  imports_weight: {en: "Imports Weight", ar: "وزن الواردات"},
  weightTon: {en: "Weight (Ton)", ar: "وزن (طن)"},
  weightTon_: {en: "Weight (Millions of tons)", ar: "الوزن (مليون طن)"},
  gastat: {en: "General Authority for Statistics (GASTAT):", ar: "الهيئة العامة للإحصاء:"},
   weight: {en: "Weight", ar: "الوزن"},
}

var scaleFactor = selector === "value" ? 1000000 : 1000
var valueWeightTranslation = selector === "value" ? ("" + (translations["value"][locale])) : ("" + (translations["weight"][locale]))
var valueWeightTooltip = selector === "value" ? ((translations["value"][locale]) + " (" + millionsOfSar + ")") : ("" + (translations["weightTon"][locale]))
var valueWeightTranslation_ = selector === "value" ? millionsOfSar : ("" + (translations["weightTon"][locale]))
var timeSelectorTranslation = time === "annual" ? ("" + (translations["year"][locale])) : ("" + (translations["month"][locale]))

return {
  cache: false,
  groupPadding: 1,
  barPadding: 1,
  axisPersist: false,
  data: [dataYear, dataMonth],
  dataFormat: function (resp) {
    var dataByYear = resp[0].data.filter(function (d) { return d[measure] > 0; }).map(function (d) { return Object.assign({}, d); });
    var dataByMonth = resp[1].data.filter(function (d) { return d[measure] > 0; }).map(function (d) { return Object.assign({}, d); });

    var lastMonth = max(dataByMonth, function (d) { return d["Month ID"]; }).toString().slice(-2)
    var lastYear = max(dataByMonth, function (d) { return d["Month ID"]; }).toString().slice(0,4)

    var cutYear = lastMonth*1 === 12 ? lastYear : (lastMonth*1 !== 12 && lastYearAvailableExports*1 !== lastYear*1) ? lastYear : lastYear - 1

    if(time === "monthly"){
      dataByMonth.forEach(function (d) {
        d["Month New"] = d["Month"].replace(/-/g, "/") + "/01";
      })
    }

    var dataFinal = time === "annual" ? dataByYear.filter(function (d) { return d["Year"]*1 <= cutYear*1; }) : dataByMonth

    dataFinal.forEach(function (d) {
      if (d["Trade Flow ID"] === 1) {
        d["Trade Flow ID"] = 2;
      } else if (d["Trade Flow ID"] === 2) {
        d["Trade Flow ID"] = 1;
      }
    });

    var importData = dataFinal.filter(function (d) { return d["Trade Flow ID"]*1 === 2; })
    var exportData = dataFinal.filter(function (d) { return d["Trade Flow ID"]*1 === 1; })

    var trade = JSON.parse(JSON.stringify(importData));

    trade.forEach(function (d) {
      var temp = exportData.find(function (h) { return h[timeID] === d[timeID]; }) || {};
      d["Export Value"] = temp[measure]
      d["Balance"] = isNaN(d["Export Value"]) ? -d[measure] : d["Export Value"] - d[measure]
    })

    trade.forEach(function (d) {
      d[measure] = selector === "value" ? d["Balance"]*1000000 : d["Balance"]
      delete d["Export Value"]
      delete d["Balance"]
      d["Trade Flow ID"] = 3
      d["Trade Flow"] = "" + (translations["tradeBalance"][locale])    
      d["Shape"] = "Line"
      d[timeSelected_] = time !== "annual" ? d["Month New"] : d["Year"] 
    })

    dataFinal.forEach(function (d) {
      d["Shape"] = "Bar"
      d[timeSelected_] = time !== "annual" ? d["Month New"] : d["Year"]
      d[measure] = d["Trade Flow ID"] === 2 ? (selector === "value" ? d["Million SAR"]*-1000000 : d["Weight TONS"]*-1) : (selector === "value" ? d["Million SAR"]*1000000 : d["Weight TONS"])
    })

    return dataFinal.concat(trade);
  },
  viewDataFormat: function (resp) {
    var dataByYear = resp[0].data.filter(function (d) { return d[measure] > 0; }).map(function (d) { return Object.assign({}, d); });
    var dataByMonth = resp[1].data.filter(function (d) { return d[measure] > 0; }).map(function (d) { return Object.assign({}, d); });

    var lastMonth = max(dataByMonth, function (d) { return d["Month ID"]; }).toString().slice(-2)
    var lastYear = max(dataByMonth, function (d) { return d["Month ID"]; }).toString().slice(0,4)

    var cutYear = lastMonth*1 === 12 ? lastYear : (lastMonth*1 !== 12 && lastYearAvailableExports*1 !== lastYear*1) ? lastYear : lastYear - 1

    if(time === "monthly"){
      dataByMonth.forEach(function (d) {
        d["Month New"] = d["Month"].replace(/-/g, "/") + "/01";
      })
    }

    var dataFinal = time === "annual" ? dataByYear.filter(function (d) { return d["Year"]*1 <= cutYear*1; }) : dataByMonth

    dataFinal.forEach(function (d) {
      if (d["Trade Flow ID"] === 1) {
        d["Trade Flow ID"] = 2;
      } else if (d["Trade Flow ID"] === 2) {
        d["Trade Flow ID"] = 1;
      }
    });

    var importData = dataFinal.filter(function (d) { return d["Trade Flow ID"]*1 === 2; })
    var exportData = dataFinal.filter(function (d) { return d["Trade Flow ID"]*1 === 1; })

    var trade = JSON.parse(JSON.stringify(importData));

    trade.forEach(function (d) {
      var temp = exportData.find(function (h) { return h[timeID] === d[timeID]; }) || {};
      d["Export Value"] = temp[measure]
      d["Balance"] = isNaN(d["Export Value"]) ? -d[measure] : d["Export Value"] - d[measure]
    })

    trade.forEach(function (d) {
      d[measure] = selector === "value" ? d["Balance"]*1000000 : d["Balance"]
      delete d["Export Value"]
      delete d["Balance"]
      d["Trade Flow ID"] = 3
      d["Trade Flow"] = "" + (translations["tradeBalance"][locale])    
      d["Shape"] = "Line"
      d[timeSelected_] = time !== "annual" ? d["Month New"] : d["Year"] 
    })

    dataFinal.forEach(function (d) {
      d["Shape"] = "Bar"
      d[timeSelected_] = time !== "annual" ? d["Month New"] : d["Year"]
      d[measure] = d["Trade Flow ID"] === 2 ? (selector === "value" ? d["Million SAR"]*-1000000 : d["Weight TONS"]*-1) : (selector === "value" ? d["Million SAR"]*1000000 : d["Weight TONS"])
    })

    var final = dataFinal.concat(trade);

    return final.map(function (d) {
      var obj;

      return (( obj = {}, obj[("" + timeSelectorTranslation)] = d[timeSelected], obj[("" + (translations["flow"][locale]))] = d["Trade Flow"], obj[("" + valueWeightTranslation)] = d["Trade Flow ID"] === 3 ? d[measure] : Math.abs(d[measure]), obj ));
    })
  },
  discrete: "x", 
  groupBy: ["Trade Flow ID"],
  label:  function (d) { return ""; },
  legendConfig: {
    label: function (d) { return d["Trade Flow"]; }
  },
  legendPosition: "bottom",
  legendSort: function (a,b) { return a["Trade Flow ID"] - b["Trade Flow ID"]; },
  legendTooltip: {
    tbody: false,
  },
  shape: function (d) { return d.Shape; },
  stacked: true,
  sourceFormat: function () {
    return [
      {
        source_name: translations.gastat[locale],
        source_link: ""
      },
      {
        source_name: translations.exports_value[locale],
        source_link: "https://database.stats.gov.sa/home/indicator/452"
      },
      {
        source_name: translations.imports_value[locale],
        source_link: "https://database.stats.gov.sa/home/indicator/448"
      } ]
  },
  title: ("" + (translations["title"][locale])),
  time: timeSelected_,//"Month New",
  timeline: true,
  timelineConfig: {
    brushing: true,
    playButton: false
  },
  tooltipConfig: {
    tbody: [
      [timeSelectorTranslation, function (d) { return d[timeSelected]; }],
      [valueWeightTooltip, function (d) { return d["Trade Flow ID"] === 3 ? decimal(d[measure]/scaleFactor) : decimal(Math.abs(d[measure])/scaleFactor); }] ]
  },
  type: "BarChart",
  x: timeSelected_,
  xConfig: {
    title: time === "annual" ? years : months
  },
  y: measure,
  yConfig: {
    title: ("" + valueWeightTranslation_),
    tickFormat: function (d) { return (d%scaleFactor === 0) ? commas(d/scaleFactor) : decimal(d/scaleFactor); },
  }
}

var tesseract = variables.tesseract;
var id = variables.id;
var name = variables.name;
var maxValueExports = variables.maxValueExports;
var secuentialYear = variables.secuentialYear;
var millionsOfSar = variables.millionsOfSar;
var thousandsOfSar = variables.thousandsOfSar;
var billionsOfSar = variables.billionsOfSar;
var months = variables.months;
var years = variables.years;
var abbreviate = formatters.abbreviate;
var commas = formatters.commas;
var pctChart = formatters.pctChart;
var sar = formatters.sar;
var lowercase = formatters.lowercase;
var decimal = formatters.decimal;
var pctDecimal = formatters.pctDecimal;
var ref = libs.d3;
var max = ref.max;
var min = ref.min;

var selector = "annual" //annual, monthly
var selectorName = "سنوي" 
var time = selector === "annual" ? "Year" : "Month"
var time_ = selector === "annual" ? "Year" : "Month New"
var timeID = selector === "annual" ? "Year" : "Month ID"

var typeChart = secuentialYear === false && selector === "annual" ? "BarChart" : "LinePlot"

var valueWeight = "value"
var valueWeightName = "القيمة"
var measure = valueWeight === "value" ? "Million SAR" : "Weight TONS"

var valueWeightName_ar = valueWeight === "weight" ? "في وزن" : "القيمة"

var translations = {
  exports: {en: "Exports", ar: "الصادرات"},
  value: {en: "Value", ar: "القيمة"},
  measure: {en: "Measure", ar: "المقياس"},
  year: {en: "Year", ar: "السنة"},
  month: {en: "Month", ar: "الشهر"},
  titleWeight: {en: (selectorName + " Evolution of the " + ((valueWeightName)) + " and Growth of Exports"),  ar: ("التطوّر ال" + selectorName + " " + valueWeightName_ar + " الصادرات ونموها")},
  titleValueYear: {en: (selectorName + " Evolution of the " + ((valueWeightName)) + " and Growth of Exports"),  ar: "التطوّر السنوي في قيمة الصادرات ونموها"},
  titleValueMonth: {en: (selectorName + " Evolution of the " + ((valueWeightName)) + " and Growth of Exports"),  ar: "التطوّر الشهري في قيمة الصادرات ونموها"},
  growthRate: {en: "Growth Rate", ar: "معدل النمو"},
  weightTon: {en: "Thousands of tons", ar: "ألف طن"},
  weight: {en: "Weight", ar: "الوزن"},
  share: {en: "Share", ar: "الحصة"},
  exports_value: {en: "Exports Value", ar: "قيمة الصادرات"},
  exports_weight: {en: "Exports Weight", ar: "وزن الصادرات"},
  gastat: {en: "General Authority for Statistics (GASTAT):", ar: "الهيئة العامة للإحصاء:"},
}

var title = {}
if (selector === "annual" && valueWeight === "value"){
  title = "" + (translations["titleValueYear"][locale])
}
else if (selector !== "annual" && valueWeight === "value"){
  title = "" + (translations["titleValueMonth"][locale])  
}
else {
  title = "" + (translations["titleWeight"][locale])  
}

var scaleFactor_  = 1000000//maxValueExports < 1 ? 1000 : maxValueExports > 1000 ? 1000000000 : 1000000
var scaleFactor = valueWeight === "value" ? scaleFactor_ : 1000
var billionOrMillion = millionsOfSar//maxValueExports < 1 ? thousandsOfSar : maxValueExports > 1000 ? billionsOfSar : millionsOfSar 

var valueWeightTranslation = valueWeight === "value" ? ("" + (translations["value"][locale])) : ("" + (translations["weight"][locale]))
var valueWeightTooltip = valueWeight === "value" ? ((translations["value"][locale]) + " (" + billionOrMillion + ")") : ("" + (translations["weightTon"][locale]))
var valueWeightTranslation_ = valueWeight === "value" ? billionOrMillion : ("" + (translations["weightTon"][locale]))
var timeSelectorTranslation = selector === "annual" ? ("" + (translations["year"][locale])) : ("" + (translations["month"][locale]))

var dataMonth = tesseract + "/data.jsonrecords?Country=" + id + "&Trade+Flow=2&cube=foreign_trade&drilldowns=Month,Year&measures=" + measure + "&locale=" + locale
var dataYear = tesseract + "/data.jsonrecords?Country=" + id + "&Trade+Flow=2&cube=foreign_trade&drilldowns=Year&measures=" + measure + "&locale=" + locale

return {
  axisPersist: false,
  baseline: 0,
  cache: false,
  data: [dataYear, dataMonth],
  dataFormat: function (resp) {
    var dataYear = resp[0].data.map(function (d) { return Object.assign({}, d); });
    var dataMonth = resp[1].data.map(function (d) { return Object.assign({}, d); });

    var lastMonth = max(dataMonth, function (d) { return d["Month ID"]; }).toString().slice(-2)
    var lastYear = max(dataMonth, function (d) { return d["Month ID"]; }).toString().slice(0,4)
    var minYear = min(dataYear, function (d) { return d["Year"]; })
    var cutYear = lastMonth*1 === 12 ? lastYear : lastYear - 1

    var dataFinal = selector === "annual" ? dataYear.filter(function (d) { return d["Year"]*1 <= cutYear*1; }) : dataMonth

    dataFinal.forEach(function (d, index) {
      var prevMonth = ""
      if(selector === "monthly"){
        prevMonth = d["Month ID"].toString().slice(-2)*1 === 1 ? 89 : 1
      }
      var prevTime = selector === "annual" ? 1 : prevMonth

      var s = dataFinal.slice(0, index).find(function (h) { return (h[timeID] * 1 === d[timeID] * 1 - prevTime); }) || {};
      d["Value Prev"] = s[measure];
      d["Growth Rate"] = ((d[measure] - d["Value Prev"]) / d["Value Prev"]) * 100;
      delete d["Value Prev"]
    });

    var data = dataFinal.filter(function (d) { return d["Year"] > minYear && d[measure] !== null; }).map(function (obj) { return (Object.assign({}, obj)); });
    data.forEach(function (d) {
      d[measure] = valueWeight === "value" ? d["Million SAR"]*1000000 : d[measure]
      d["Trend Figure"] = valueWeightTranslation
      d["Trend Figure ID"] = valueWeight === "value" ? "1111": "3333"
      delete d["Growth Rate"]
    });

    var dataGrowth = dataFinal.filter(function (d) { return d["Year"] > minYear; }).filter(function (d) { return Number.isFinite(d["Growth Rate"]); }).map(function (obj) { return (Object.assign({}, obj)); });
    dataGrowth.forEach(function (d) {
      d["Trend Figure"] = "" + (translations["growthRate"][locale])
      d["Trend Figure ID"] = "2222"
      delete d[measure]
    });

    var lastData = data.concat(dataGrowth)
    if(selector === "monthly") {
      lastData.forEach(function (d) {
        d["Month New"] = d["Month"].replace(/-/g, "/") + "/01";
      })
    }
    return lastData
  },
  viewDataFormat: function (resp) {
    var dataYear = resp[0].data.map(function (d) { return Object.assign({}, d); });
    var dataMonth = resp[1].data.map(function (d) { return Object.assign({}, d); });

    var lastMonth = max(dataMonth, function (d) { return d["Month ID"]; }).toString().slice(-2)
    var lastYear = max(dataMonth, function (d) { return d["Month ID"]; }).toString().slice(0,4)
    var minYear = min(dataYear, function (d) { return d["Year"]; })
    var cutYear = lastMonth === 12 ? lastYear : lastYear - 1

    var dataFinal = selector === "annual" ? dataYear.filter(function (d) { return d["Year"] <= cutYear; }) : dataMonth

    dataFinal.forEach(function (d, index) {
      var prevMonth = ""
      if(selector === "monthly"){
         prevMonth = d["Month ID"].toString().slice(-2)*1 === 1 ? 89 : 1
      }

      var prevTime = selector === "annual" ? 1 : prevMonth

      var s = dataFinal.slice(0, index).find(function (h) { return (h[timeID] * 1 === d[timeID] * 1 - prevTime); }) || {};
      d["Value Prev"] = s[measure];
      d["Growth Rate"] = ((d[measure] - d["Value Prev"]) / d["Value Prev"]) * 100;
      delete d["Value Prev"]
    });

    var data = dataFinal.filter(function (d) { return d["Year"] > minYear; }).map(function (obj) { return (Object.assign({}, obj)); });
    data.forEach(function (d) {
      d["Trend Figure"] = valueWeightTranslation
      d["Trend Figure ID"] = valueWeight === "value" ? "1111": "3333"
      delete d["Growth Rate"]
    });

    var dataGrowth = dataFinal.filter(function (d) { return d["Year"] > minYear; }).map(function (obj) { return (Object.assign({}, obj)); });
    dataGrowth.forEach(function (d) {
      d["Trend Figure"] = "" + (translations["growthRate"][locale])
      d["Trend Figure ID"] = "2222"
      delete d[measure]
    });

    var mergedData = [];

    data.forEach(function (d) {
        mergedData.push({
            Year: d[time],
            Measure: valueWeightTranslation,
            Value: d[measure]
        });
    });

    dataGrowth.forEach(function (d) {
        mergedData.push({
            Year: d[time],
            Measure:("" + (translations["growthRate"][locale])),
            Value: d["Growth Rate"]
        });
    });

    return mergedData.map(function (d) {
      var obj;

      return (( obj = {}, obj[timeSelectorTranslation] = d["Year"], obj[("" + (translations["measure"][locale]))] = d["Measure"], obj[("" + (translations["value"][locale]))] = d["Value"], obj ));
    })
  },
  discrete: "x",
  groupBy: "Trend Figure ID",
  label: function (d) { return ""; },
  legend: true,
  legendConfig: {
    label: function (d) { return d["Trend Figure"]; }
  },
  legendPosition: "bottom",
  legendTooltip: {
    tbody: false,
  },
  lineMarkers: true,
  lineMarkerConfig: {
    r: 3,
  },
  shapeConfig: {
    Line: {
      curve: "Linear"
    }
  },
  sourceFormat: function () {
    return [
      {
        source_name: translations.gastat[locale],
        source_link: ""
      },
      {
        source_name: translations.exports_value[locale],
        source_link: "https://database.stats.gov.sa/home/indicator/448"
      },
      {
        source_name: translations.exports_weight[locale],
        source_link: "https://database.stats.gov.sa/home/indicator/449"
      } ]
  },
  tooltipConfig: {
    title: function (d) { return d["Trend Figure"]; },
    tbody: function (d) {
      var customTooltip = [];
      d["Trend Figure ID"] === "2222" ?
      customTooltip = [
        [timeSelectorTranslation, d[time]],
        [("" + (translations["growthRate"][locale])), ("" + (pctDecimal(d["Growth Rate"] * 1)))] ] : 
      customTooltip = [
        [timeSelectorTranslation, d[time]],
        [valueWeightTooltip, (valueWeight !== "value") ? decimal(d[measure]/scaleFactor) : decimal(d[measure]/scaleFactor)] ]
    return customTooltip;
    },
  },
  title: title,
  type: "LinePlot",
  time: time_,
  timeline: true,
  timelineConfig: {
    brushing: true,
    playButton: false
  },
  x: time_,
  xConfig: {
    title: selector === "annual" ? years : months
  },
  y: measure,
  yConfig: {
    tickFormat: function (d) { return (d%scaleFactor === 0) ? commas(d/scaleFactor) : decimal(d/scaleFactor); },
    title: ((translations["exports"][locale]) + " (" + valueWeightTranslation_ + ")"),

  },
  y2: "Growth Rate",
  y2Config: {
    tickFormat: function (d) { return pctChart(d); },//locale === "en" ? `${commas(Math.round(d))}%` : `%${commas(Math.round(d))}`,
    title: ("" + (translations["growthRate"][locale]))
  },
};

var tesseract = variables.tesseract;
var id = variables.id;
var name = variables.name;
var lastYearAvailableExports = variables.lastYearAvailableExports;
var billionsOfSar = variables.billionsOfSar;
var decimal = formatters.decimal;
var pctDecimal = formatters.pctDecimal;
var ref = libs.d3;
var nest = ref.nest;
var sum = ref.sum;
var max = ref.max;

var selector = "value"
var selectorName = "القيمة"
var measure = selector === "value" ? "Million SAR" : "Weight TONS"

var time = "annual"// annual, monthly
var timeSelected = time === "annual" ? "Year" : "Month"
var timeSelected_ = time === "annual" ? "Year" : "Month New"

var translations = {
  value: {en: "Value", ar: "القيمة"},
  titleValue: {en: ("Section Wise Exports to " + name), ar: ("المنتجات المصدرة إلى " + name + " حسب " + selectorName + " التجارية")},
  titleWeight: {en: ("Section Wise Exports to " + name), ar: ("المنتجات المصدرة إلى " + name + " حسب " + selectorName)},
  section: {en: "Section", ar: "القسم"},
  year: {en: "Year", ar: "السنة"},
  month: {en: "Month", ar: "الشهر"},
  hs2: {en: "HS2", ar: "HS2"},
  millionSAR: {en: "SAR Million", ar: "مليون ريال سعودي"},
  weightTon: {en: "Weight (Ton)", ar: "وزن (طن)"},
  share: {en: "Share", ar: "الحصة"},
  value_: {en: ("Value (" + billionsOfSar + ")"), ar: ("القيمة (" + billionsOfSar + ")")},
  weightTon_: {en: "Weight (Millions of tons)", ar: "الوزن (مليون طن)"},
  exports_value: {en: "Exports Value", ar: "قيمة الصادرات"},
  exports_weight: {en: "Exports Weight", ar: "وزن الصادرات"},
  gastat: {en: "General Authority for Statistics (GASTAT):", ar: "الهيئة العامة للإحصاء:"},
}

var valueWeight = selector === "value" ? ("" + (translations["millionSAR"][locale])) : ("" + (translations["weightTon"][locale]))
var valueWeight_ = selector === "value" ? ("" + (translations["value_"][locale])) : ("" + (translations["weightTon_"][locale]))
var valueWeightTooltip = selector === "value" ? ("" + (translations["value"][locale])) : ("" + (translations["weightTon"][locale]))
